Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
tls: Purge async_hold in tls_decrypt_async_wait()

The async_hold queue pins encrypted input skbs while
the AEAD engine references their scatterlist data. Once
tls_decrypt_async_wait() returns, every AEAD operation
has completed and the engine no longer references those
skbs, so they can be freed unconditionally.

A subsequent patch adds batch async decryption to
tls_sw_read_sock(), introducing a new call site that
must drain pending AEAD operations and release held
skbs. Move __skb_queue_purge(&ctx->async_hold) into
tls_decrypt_async_wait() so the purge is centralized
and every caller -- recvmsg's drain path, the -EBUSY
fallback in tls_do_decryption(), and the new read_sock
batch path -- releases held skbs on synchronization
without each site managing the purge independently.

This fixes a leak when tls_strp_msg_hold() fails part-way through,
after having added some cloned skbs to the async_hold
queue. tls_decrypt_sg() will then call tls_decrypt_async_wait() to
process all pending decrypts, and drop back to synchronous mode, but
tls_sw_recvmsg() only flushes the async_hold queue when one record has
been processed in "fully-async" mode, which may not be the case here.

Signed-off-by: Chuck Lever <chuck.lever@oracle.com>
Reported-by: Yiming Qian <yimingqian591@gmail.com>
Fixes: b8a6ff84abbc ("tls: wait for pending async decryptions if tls_strp_msg_hold fails")
Link: https://patch.msgid.link/20260324-tls-read-sock-v5-1-5408befe5774@oracle.com
[pabeni@redhat.com: added leak comment]
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The async_hold queue stores encrypted input skbs pinned for async AEAD operations. The cleanup (purge) of this queue was only performed in `tls_sw_recvmsg()` when processing a record in fully-async mode, but other code paths that wait for pending async decryptions (e.g., the `-EBUSY` fallback in `tls_do_decryption()` or the call from `tls_decrypt_sg()` when `tls_strp_msg_hold()` fails) also call `tls_decrypt_async_wait()` without purging the queue, causing a memory leak of those skbs. The fix centralizes the purge into `tls_decrypt_async_wait()` so all callers properly release the held skbs.

Here is the patch:

 static int tls_decrypt_async_wait(struct tls_sw_context_rx *ctx)
 {
 	if (!atomic_dec_and_test(&ctx->decrypt_pending))
 		crypto_wait_req(-EINPROGRESS, &ctx->async_wait);
 	atomic_inc(&ctx->decrypt_pending);

+	__skb_queue_purge(&ctx->async_hold);
 	return ctx->async_wait.err;
 }


 int tls_sw_recvmsg(struct sock *sk,
 		   struct msghdr *msg,
 		   size_t len,
 		   int flags,
 		   int *addr_len)
 {
 	struct tls_context *tls_ctx = tls_get_ctx(sk);
 	struct tls_sw_context_rx *ctx = tls_sw_ctx_rx(tls_ctx);
 	struct tls_prot_info *prot = &tls_ctx->prot_info;
 	ssize_t decrypted = 0, async_copy_bytes = 0;
 	struct sk_psock *psock;
 	unsigned char control = 0;
 	size_t flushed_at = 0;
 	struct strp_msg *rxm;
 	struct tls_msg *tlm;
 	ssize_t copied = 0;
 	ssize_t peeked = 0;
 	bool async = false;
 	int target, err;
 	bool is_kvec = iov_iter_is_kvec(&msg->msg_iter);
 	bool is_peek = flags & MSG_PEEK;
 	bool rx_more = false;
 	bool released = true;
 	bool bpf_strp_enabled;
 	bool zc_capable;

 	if (unlikely(flags & MSG_ERRQUEUE))
 		return sock_recv_errqueue(sk, msg, len, SOL_IP, IP_RECVERR);

 	err = tls_rx_reader_lock(sk, ctx, flags & MSG_DONTWAIT);
 	if (err < 0)
 		return err;
 	psock = sk_psock_get(sk);
 	bpf_strp_enabled = sk_psock_strp_enabled(psock);

 	/* If crypto failed the connection is broken */
 	err = ctx->async_wait.err;
 	if (err)
 		goto end;

 	/* Process pending decrypted records. It must be non-zero-copy */
 	err = process_rx_list(ctx, msg, &control, 0, len, is_peek, &rx_more);
 	if (err < 0)
 		goto end;

 	/* process_rx_list() will set @control if it processed any records */
 	copied = err;
 	if (len <= copied || rx_more ||
 	    (control && control != TLS_RECORD_TYPE_DATA))
 		goto end;

 	target = sock_rcvlowat(sk, flags & MSG_WAITALL, len);
 	len = len - copied;

 	zc_capable = !bpf_strp_enabled && !is_kvec && !is_peek &&
 		ctx->zc_capable;
 	decrypted = 0;
 	while (len && (decrypted + copied < target || tls_strp_msg_ready(ctx))) {
 		struct tls_decrypt_arg darg;
 		int to_decrypt, chunk;

 		err = tls_rx_rec_wait(sk, psock, flags & MSG_DONTWAIT,
 				      released);
 		if (err <= 0) {
 			if (psock) {
 				chunk = sk_msg_recvmsg(sk, psock, msg, len,
 						       flags);
 				if (chunk > 0) {
 					decrypted += chunk;
 					len -= chunk;
 					continue;
 				}
 			}
 			goto recv_end;
 		}

 		memset(&darg.inargs, 0, sizeof(darg.inargs));

 		rxm = strp_msg(tls_strp_msg(ctx));
 		tlm = tls_msg(tls_strp_msg(ctx));

 		to_decrypt = rxm->full_len - prot->overhead_size;

 		if (zc_capable && to_decrypt <= len &&
 		    tlm->control == TLS_RECORD_TYPE_DATA)
 			darg.zc = true;

 		/* Do not use async mode if record is non-data */
 		if (tlm->control == TLS_RECORD_TYPE_DATA && !bpf_strp_enabled)
 			darg.async = ctx->async_capable;
 		else
 			darg.async = false;

 		err = tls_rx_one_record(sk, msg, &darg);
 		if (err < 0) {
 			tls_err_abort(sk, -EBADMSG);
 			goto recv_end;
 		}

 		async |= darg.async;

 		/* If the type of records being processed is not known yet,
 		 * set it to record type just dequeued. If it is already known,
 		 * but does not match the record type just dequeued, go to end.
 		 * We always get record type here since for tls1.2, record type
 		 * is known just after record is dequeued from stream parser.
 		 * For tls1.3, we disable async.
 		 */
 		err = tls_record_content_type(msg, tls_msg(darg.skb), &control);
 		if (err <= 0) {
 			DEBUG_NET_WARN_ON_ONCE(darg.zc);
 			tls_rx_rec_done(ctx);
 put_on_rx_list_err:
 			__skb_queue_tail(&ctx->rx_list, darg.skb);
 			goto recv_end;
 		}

 		/* periodically flush backlog, and feed strparser */
 		released = tls_read_flush_backlog(sk, prot, len, to_decrypt,
 						  decrypted + copied,
 						  &flushed_at);

 		/* TLS 1.3 may have updated the length by more than overhead */
 		rxm = strp_msg(darg.skb);
 		chunk = rxm->full_len;
 		tls_rx_rec_done(ctx);

 		if (!darg.zc) {
 			bool partially_consumed = chunk > len;
 			struct sk_buff *skb = darg.skb;

 			DEBUG_NET_WARN_ON_ONCE(darg.skb == ctx->strp.anchor);

 			if (async) {
 				/* TLS 1.2-only, to_decrypt must be text len */
 				chunk = min_t(int, to_decrypt, len);
 				async_copy_bytes += chunk;
 put_on_rx_list:
 				decrypted += chunk;
 				len -= chunk;
 				__skb_queue_tail(&ctx->rx_list, skb);
 				if (unlikely(control != TLS_RECORD_TYPE_DATA))
 					break;
 				continue;
 			}

 			if (bpf_strp_enabled) {
 				released = true;
 				err = sk_psock_tls_strp_read(psock, skb);
 				if (err != __SK_PASS) {
 					rxm->offset = rxm->offset + rxm->full_len;
 					rxm->full_len = 0;
 					if (err == __SK_DROP)
 						consume_skb(skb);
 					continue;
 				}
 			}

 			if (partially_consumed)
 				chunk = len;

 			err = skb_copy_datagram_msg(skb, rxm->offset,
 						    msg, chunk);
 			if (err < 0)
 				goto put_on_rx_list_err;

 			if (is_peek) {
 				peeked += chunk;
 				goto put_on_rx_list;
 			}

 			if (partially_consumed) {
 				rxm->offset += chunk;
 				rxm->full_len -= chunk;
 				goto put_on_rx_list;
 			}

 			consume_skb(skb);
 		}

 		decrypted += chunk;
 		len -= chunk;

 		/* Return full control message to userspace before trying
 		 * to parse another message type
 		 */
 		msg->msg_flags |= MSG_EOR;
 		if (control != TLS_RECORD_TYPE_DATA)
 			break;
 	}

 recv_end:
 	if (async) {
 		int ret;

 		/* Wait for all previously submitted records to be decrypted */
 		ret = tls_decrypt_async_wait(ctx);
-		__skb_queue_purge(&ctx->async_hold);

 		if (ret) {
 			if (err >= 0 || err == -EINPROGRESS)
 				err = ret;
 			goto end;
 		}

 		/* Drain records from the rx_list & copy if required */
 		if (is_peek)
 			err = process_rx_list(ctx, msg, &control, copied + peeked,
 					      decrypted - peeked, is_peek, NULL);
 		else
 			err = process_rx_list(ctx, msg, &control, 0,
 					      async_copy_bytes, is_peek, NULL);

 		/* we could have copied less than we wanted, and possibly nothing */
 		decrypted += max(err, 0) - async_copy_bytes;
 	}

 	copied += decrypted;

 end:
 	tls_rx_reader_unlock(sk, ctx);
 	if (psock)
 		sk_psock_put(sk, psock);
 	return copied ? : err;
 }



